import{_ as t,o,c as d,ah as c}from"./chunks/framework.rk_qxSDs.js";const p=JSON.parse('{"title":"Swagger UI Configuration","description":"All options of the swagger-ui plugin, the OAuth options and the content security policy.","frontmatter":{"title":"Swagger UI Configuration","description":"All options of the swagger-ui plugin, the OAuth options and the content security policy.","relatedPlugins":["decorators"]},"headers":[],"relativePath":"swagger-ui/configuration.md","filePath":"swagger-ui/configuration.md","lastUpdated":1794920275000}'),a={name:"swagger-ui/configuration.md"};function r(s,e,i,n,h,l){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p><code>swaggerUI(document, options?)</code> takes the options as its second argument; every option is optional. The options are the <code>UIOptions</code> type: the Swagger UI configuration (<code>SwaggerConfigs</code> from <code>@types/swagger-ui-dist</code>) plus the fields of this plugin. Options are checked when the plugin is installed with <code>app.use()</code>, and an invalid one throws there.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>basePath</code></td><td><code>string</code></td><td>none</td><td>Path prefix the app is reachable under behind a proxy; put in front of the mount path in <code>&lt;base href&gt;</code></td></tr><tr><td><code>baseURL</code></td><td><code>string</code></td><td>none</td><td>Absolute <code>http:</code> or <code>https:</code> URL the app is reachable under; the mount path is resolved against it for <code>&lt;base href&gt;</code>. Wins over <code>basePath</code></td></tr><tr><td><code>oauth</code></td><td><code>UIOAuthOptions</code></td><td>none</td><td>Passed to <code>ui.initOAuth()</code>; also serves the OAuth redirect page</td></tr><tr><td><code>authAction</code></td><td><code>Record&lt;string, any&gt;</code></td><td>none</td><td>Passed to <code>ui.authActions.authorize()</code> to authorize security schemes up front</td></tr><tr><td><code>oauth2RedirectUrl</code></td><td><code>string</code></td><td><code>oauth2-redirect.html</code> next to <code>&lt;base href&gt;</code></td><td>OAuth redirect URL passed to Swagger UI; setting it also serves the OAuth redirect page</td></tr><tr><td><code>validatorUrl</code></td><td><code>string | null</code></td><td>Swagger UI&#39;s, <code>https://validator.swagger.io/validator</code></td><td>Validator of the badge that <code>StandaloneLayout</code> shows for a document loaded by URL; <code>null</code> or <code>&#39;none&#39;</code> turns it off</td></tr><tr><td><code>csp</code></td><td><code>boolean | string | ContentSecurityPolicyInput</code></td><td><code>false</code></td><td>Sends a <code>content-security-policy</code> header with every response</td></tr><tr><td><code>securityHeaders</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Sends <code>x-content-type-options</code>, <code>referrer-policy</code> and <code>x-frame-options</code> with every response</td></tr><tr><td><code>spec</code></td><td><code>Spec</code></td><td>set from <code>document</code></td><td>Replaced by the <code>document</code> argument when it is an object or a file; next to a URL document it is passed on as well</td></tr><tr><td><code>url</code></td><td><code>string</code></td><td>set from <code>document</code></td><td>Replaced by the <code>document</code> argument when it is a URL; next to an object or file document it is passed on as well</td></tr><tr><td><code>layout</code></td><td><code>string</code></td><td><code>&#39;BaseLayout&#39;</code></td><td>Top-level layout component of Swagger UI</td></tr><tr><td><code>dom_id</code></td><td><code>string | null</code></td><td><code>&#39;#swagger-ui&#39;</code></td><td>Element the UI renders into; the shell has <code>&lt;div id=&quot;swagger-ui&quot;&gt;</code></td></tr><tr><td><code>deepLinking</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Deep links for tags and operations</td></tr><tr><td><code>presets</code></td><td><code>any[]</code></td><td><code>[SwaggerUIBundle.presets.apis, SwaggerUIStandalonePreset]</code></td><td>Swagger UI presets</td></tr><tr><td><code>plugins</code></td><td><code>any</code></td><td><code>[SwaggerUIBundle.plugins.DownloadUrl]</code></td><td>Swagger UI plugins</td></tr></tbody></table><p>The other keys of <code>SwaggerConfigs</code> (<code>urls</code>, <code>configUrl</code>, <code>domNode</code>, <code>docExpansion</code>, <code>maxDisplayedTags</code>, <code>operationsSorter</code>, <code>requestInterceptor</code>, <code>responseInterceptor</code>) and, through its index signature, any key such as <code>persistAuthorization</code> are passed to Swagger UI unchanged; the <a href="https://swagger.io/docs/open-source-tools/swagger-ui/usage/configuration/" target="_blank" rel="noreferrer">Swagger UI configuration</a> describes them.</p><p>The options, except <code>basePath</code>, <code>baseURL</code>, <code>csp</code> and <code>securityHeaders</code>, are written into the generated <code>swagger-initializer.js</code>, which merges them over the defaults in the table and passes the result to <code>SwaggerUIBundle()</code>. <code>oauth</code> and <code>authAction</code> are taken out first and applied to the created UI. The options object you pass is not modified.</p><ul><li><strong>Values are escaped.</strong> <code>&lt;</code>, <code>&gt;</code>, <code>&amp;</code>, U+2028 and U+2029 in the document and the options are escaped, so a description containing <code>&lt;/script&gt;</code> or <code>&lt;!--</code> cannot break out of the script.</li><li><strong>Functions are passed as source.</strong> A function value, such as <code>requestInterceptor</code>, is inserted by its source text and runs in the browser, so it cannot use variables of your server code. A bound or native function (<code>fn.bind(...)</code>, <code>Math.max</code>) has no source to pass and throws at <code>app.use()</code>.</li></ul><h3 id="basepath" tabindex="-1"><code>basePath</code> <a class="header-anchor" href="#basepath" aria-label="Permalink to &quot;`basePath`&quot;">​</a></h3><p>For an app behind a reverse proxy that forwards a path prefix: <code>basePath: &#39;/backend/&#39;</code> with a mount at <code>/docs</code> gives <code>&lt;base href=&quot;/backend/docs/&quot;&gt;</code>. <a href="/swagger-ui/recipes#behind-a-reverse-proxy">Behind a Reverse Proxy</a> shows it with a nested app.</p><h3 id="baseurl" tabindex="-1"><code>baseURL</code> <a class="header-anchor" href="#baseurl" aria-label="Permalink to &quot;`baseURL`&quot;">​</a></h3><p>The public URL of the app, for a shell served under another origin or prefix: <code>baseURL: &#39;https://example.com/api/&#39;</code> with a mount at <code>/v2/docs</code> gives <code>&lt;base href=&quot;https://example.com/api/v2/docs/&quot;&gt;</code>. Its path is treated as a directory, so <code>https://example.com/api</code> behaves like <code>https://example.com/api/</code>; a query or fragment is dropped. With <code>csp</code>, its origin is added to the directives that load the files of the UI.</p><p>Anything other than an absolute <code>http:</code> or <code>https:</code> URL throws at <code>app.use()</code>. When both are set, <code>baseURL</code> wins over <code>basePath</code>.</p><h3 id="oauth" tabindex="-1"><code>oauth</code> <a class="header-anchor" href="#oauth" aria-label="Permalink to &quot;`oauth`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>scopes</code></td><td><code>string[] | string</code></td><td>Required. Scopes selected by default</td></tr><tr><td><code>clientId</code></td><td><code>string</code></td><td>OAuth client id</td></tr><tr><td><code>clientSecret</code></td><td><code>string</code></td><td>OAuth client secret; it is sent to every visitor of the UI</td></tr><tr><td><code>realm</code></td><td><code>string</code></td><td>Realm query parameter, for OAuth 1</td></tr><tr><td><code>appName</code></td><td><code>string</code></td><td>Application name shown in the authorization popup</td></tr><tr><td><code>scopeOperator</code></td><td><code>string</code></td><td>Separator of the scopes in the authorization request</td></tr><tr><td><code>additionalQueryStringParams</code></td><td><code>Record&lt;string, any&gt;</code></td><td>Extra query parameters of the authorization and token request</td></tr><tr><td><code>useBasicAuthenticationWithAccessCodeGrant</code></td><td><code>boolean</code></td><td>Sends the client credentials as basic authentication in the access code flow</td></tr><tr><td><code>usePkceWithAuthorizationCodeGrant</code></td><td><code>boolean</code></td><td>Uses PKCE in the authorization code flow</td></tr></tbody></table><p>The object is passed to <code>ui.initOAuth()</code> as is (<a href="https://swagger.io/docs/open-source-tools/swagger-ui/usage/oauth2/" target="_blank" rel="noreferrer">Swagger UI OAuth2 configuration</a>). Setting it also serves <code>oauth2-redirect.html</code> and <code>oauth2-redirect.js</code> (<a href="/swagger-ui/#served-files">Served Files</a>). <a href="/swagger-ui/recipes#oauth-login">OAuth Login</a> shows it.</p><h3 id="authaction" tabindex="-1"><code>authAction</code> <a class="header-anchor" href="#authaction" aria-label="Permalink to &quot;`authAction`&quot;">​</a></h3><p>Passed to <code>ui.authActions.authorize()</code> after the UI is created, for example to fill in an API key: <code>{ apiKey: { name: &#39;apiKey&#39;, schema: { type: &#39;apiKey&#39;, in: &#39;header&#39;, name: &#39;x-api-key&#39; }, value: &#39;...&#39; } }</code>. Like every option, it is sent to the browser.</p><h3 id="oauth2redirecturl" tabindex="-1"><code>oauth2RedirectUrl</code> <a class="header-anchor" href="#oauth2redirecturl" aria-label="Permalink to &quot;`oauth2RedirectUrl`&quot;">​</a></h3><p>Without it, the bootstrap sets the redirect URL to <code>oauth2-redirect.html</code> resolved against <code>&lt;base href&gt;</code>, so OAuth works for <code>/docs</code> and <code>/docs/</code> alike. Setting it, like <code>oauth</code>, also serves the redirect page. For a document loaded by URL, which the plugin cannot inspect for OAuth schemes, set one of the two to serve the page.</p><h3 id="csp" tabindex="-1"><code>csp</code> <a class="header-anchor" href="#csp" aria-label="Permalink to &quot;`csp`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>origins</code></td><td><code>string[]</code></td><td>More origins the UI is served from; added to every fetch directive and <code>base-uri</code>, not to <code>form-action</code></td></tr><tr><td><code>connectSrc</code></td><td><code>string[]</code></td><td>More <code>connect-src</code> sources: the document URL, API servers, token endpoints</td></tr><tr><td><code>imgSrc</code></td><td><code>string[]</code></td><td>More <code>img-src</code> sources</td></tr><tr><td><code>frameAncestors</code></td><td><code>string[]</code></td><td><code>frame-ancestors</code> sources; absent or empty: <code>&#39;none&#39;</code></td></tr></tbody></table><p>The table is <code>ContentSecurityPolicyInput</code>. <code>csp</code> takes one of:</p><table tabindex="0"><thead><tr><th>Value</th><th><code>content-security-policy</code></th></tr></thead><tbody><tr><td><code>false</code> (default)</td><td>none</td></tr><tr><td><code>true</code></td><td>The recommended policy, with the origins derived from the options and the document</td></tr><tr><td><code>ContentSecurityPolicyInput</code></td><td>The recommended policy with these sources added; <code>{}</code> behaves like <code>true</code></td></tr><tr><td><code>string</code></td><td>This string as is</td></tr></tbody></table><p>The shell loads only same-origin files and has no inline script or style, so it runs under <code>script-src &#39;self&#39;; style-src &#39;self&#39;</code>. Every response of the plugin carries the header, <code>304</code> responses included. The recommended policy without any derived origin:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>default-src &#39;none&#39;; script-src &#39;self&#39;; style-src &#39;self&#39;; img-src &#39;self&#39; data: blob:;</span></span>\n<span class="line"><span>media-src &#39;self&#39; blob:; font-src &#39;self&#39;; connect-src &#39;self&#39;; worker-src &#39;none&#39;;</span></span>\n<span class="line"><span>base-uri &#39;self&#39;; form-action &#39;self&#39;; frame-ancestors &#39;none&#39;</span></span></code></pre></div><ul><li><code>default-src &#39;none&#39;</code> closes the fetch directives without a named fallback (objects, frames, manifests). <code>script-src-elem</code>, <code>script-src-attr</code>, <code>style-src-elem</code> and <code>style-src-attr</code> follow <code>script-src</code> and <code>style-src</code>.</li><li><code>worker-src &#39;none&#39;</code> forbids workers, which would otherwise fall back to <code>script-src &#39;self&#39;</code>, not to <code>default-src</code>.</li><li><code>frame-ancestors &#39;none&#39;</code> forbids framing the UI on any site.</li><li><code>data:</code> images are used by <code>swagger-ui.css</code>; <code>blob:</code> lets &quot;Try it out&quot; show binary responses (images, audio, video).</li></ul><p>Origins derived from the options and the document go to <code>connect-src</code>: the document URL, <code>configUrl</code>, the <code>urls[]</code> entries, the <code>servers</code> of an object or file document at root, path and operation level and the Swagger 2 <code>host</code> (with its <code>schemes</code>, by default <code>https</code> and <code>http</code>), and its OAuth token, refresh and OpenID Connect URLs.</p><ul><li>Templated server URLs are expanded with the <code>default</code> and every <code>enum</code> value of their variables, each variable once for all its occurrences. Above 64 combinations per server, only the defaults are used. A variable without a value leaves the server out.</li><li>A protocol-relative server (<code>//api.example.com</code>) adds its <code>https:</code> and its <code>http:</code> origin.</li><li>Only origins of the form <code>scheme://host[:port]</code> (letters, digits, <code>.</code>, <code>-</code> or a bracketed IPv6 address) are added; any other server value is dropped.</li><li>The <code>baseURL</code> origin is added to <code>script-src</code>, <code>style-src</code>, <code>img-src</code>, <code>media-src</code>, <code>font-src</code>, <code>connect-src</code> and <code>base-uri</code>; <code>default-src</code> stays <code>&#39;none&#39;</code> and <code>form-action</code> stays <code>&#39;self&#39;</code>.</li><li>With <code>layout: &#39;StandaloneLayout&#39;</code> and a document loaded by URL, the origin of the validator badge (<code>validatorUrl</code>, unless it is <code>null</code> or <code>&#39;none&#39;</code>) is added to <code>img-src</code>.</li></ul><p>Some origins cannot be known in advance; add them with the object or use a string policy: the servers of a document loaded by URL, a server variable without a value or one a visitor types freely (no <code>enum</code>), and an OpenID Connect <code>token_endpoint</code> found through discovery on another origin than the <code>openIdConnectUrl</code>.</p><p>A source in the object that is empty or contains whitespace, a control character, <code>;</code> or <code>,</code> throws at <code>app.use()</code>, since it would add a directive or a second policy. Source expressions such as <code>&#39;self&#39;</code>, <code>data:</code>, <code>https:</code> or <code>*.example.com</code> are accepted. <a href="/swagger-ui/recipes#embed-in-a-portal">Embed in a Portal</a> shows the object; <a href="/swagger-ui/helpers#buildcontentsecuritypolicy"><code>buildContentSecurityPolicy()</code></a> builds the same policy for a header of your own.</p><h3 id="securityheaders" tabindex="-1"><code>securityHeaders</code> <a class="header-anchor" href="#securityheaders" aria-label="Permalink to &quot;`securityHeaders`&quot;">​</a></h3><p>With <code>true</code>, every response of the plugin, <code>304</code> responses included, carries:</p><table tabindex="0"><thead><tr><th>Header</th><th>Value</th></tr></thead><tbody><tr><td><code>x-content-type-options</code></td><td><code>nosniff</code></td></tr><tr><td><code>referrer-policy</code></td><td><code>no-referrer</code></td></tr><tr><td><code>x-frame-options</code></td><td><code>DENY</code>; <code>SAMEORIGIN</code> when <code>csp</code> is an object whose <code>frameAncestors</code> is exactly <code>[&quot;&#39;self&#39;&quot;]</code>; none when <code>frameAncestors</code> names any other source, which the header cannot express</td></tr></tbody></table><p>It works with or without <code>csp</code>. With a string <code>csp</code>, <code>x-frame-options</code> is <code>DENY</code>; a browser that reads <code>frame-ancestors</code> from your policy ignores <code>x-frame-options</code>.</p><h3 id="layout" tabindex="-1"><code>layout</code> <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;`layout`&quot;">​</a></h3><p>The default <code>BaseLayout</code> has no top bar: the page shows the configured document only, with no field to load another document by URL. <code>layout: &#39;StandaloneLayout&#39;</code> brings the top bar back, including that field; its logo then needs an inline style, which <code>style-src &#39;self&#39;</code> blocks, and the UI still works.</p>',36)])])}const g=t(a,[["render",r]]);export{p as __pageData,g as default};
